def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # Marker coordinates are centers of the 3x3 object template. Each stamp
    # uses the source object's shape and colors relative to its central 5.
    shape=[(-1,-1,7),(-1,0,7),(-1,1,5),(0,-1,7),(0,0,5),(0,1,7),(1,-1,5),(1,0,7),(1,1,5)]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==6:
                for dr,dc,v in shape:
                    rr,cc=r+dr,c+dc
                    if 0<=rr<h and 0<=cc<w and grid[rr][cc]==9: out[rr][cc]=v
    return out

def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    pattern=[(0,0,7),(0,1,7),(0,2,5),(0,3,7),(0,4,5)]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==6:
                for dr,dc,v in pattern:
                    rr,cc=r+dr,c+dc
                    if rr<h and cc<w: out[rr][cc]=v
    return out
